--
-- Table structure for table `people`
--

CREATE TABLE `people` (
  `id` smallint(4) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `public` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Binary switch to make record public.',
  `name` varchar(128) COLLATE utf8_unicode_ci NOT NULL COMMENT 'Display name',
  `shortname` varchar(32) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Short name, for use in winner references, etc.',
  `taskmaster` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Has appeared as a Taskmaster?',
  `active_taskmaster` tinyint(1) UNSIGNED DEFAULT NULL COMMENT 'Binary indicator of whether they are a currently active Taskmaster',
  `assistant` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Has appeared as a Taskmaster''s assistant?',
  `active_assistant` tinyint(1) UNSIGNED DEFAULT NULL COMMENT 'Binary indicator of whether they are a currently active assistant',
  `contestant` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Has appeared as a contestant?',
  `guest` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Has appeared as a guest?',
  `tags` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Career tags',
  `meta_tag_bio` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Short basic bio used for social media meta tags.',
  `taskmaster_notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Notes on their thoughts, reflections and insights on Taskmaster (use pipes to separate bullets).',
  `recurring_bits` varchar(2048) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Notes on any recurring bits performed by or linked to the contestant during their appearances.',
  `imdb` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'IMDb link',
  `instagram` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Instagram link',
  `spotify` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Spotify link',
  `tiktok` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'TikTok link',
  `twitch` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Twitch',
  `web` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Web link',
  `wikipedia` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Wikipedia link',
  `youtube` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'YouTube link',
  `headshot_image` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Headshot image filename',
  `headshot_image_metatag` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Headshot image for use in metatags only.',
  `headshot_image_pinky` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Headshot image pinky filename',
  `headshot_image_search` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Version of headshot metatag image cropped for appearance in search results.',
  `headshot_image_thumb` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Headshot image thumbnail filename',
  `headshot_image_credit` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Credit text for image'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

