(24, 1, 'Mel Giedroyc', 'Mel', 0, NULL, 0, NULL, 1, 0, '|actor|comedian|presenter|screenwriter|', 'Mel is an actor, comedian and presenter who has appeared as a contestant on Taskmaster.', NULL, 'Mel pocketed the wax seals from every task she opened. Also, Alex wore a tie or bow tie during the filming of every one of Mel\'s tasks.', 'https://www.imdb.com/name/nm0317329/', NULL, NULL, NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/Mel_Giedroyc', NULL, '0024_mel_giedroyc.png', '0024_mel_giedroyc_metatag.jpg', '0024_mel_giedroyc_pinky.png', '0024_mel_giedroyc_search.jpg', '0024_mel_giedroyc_thumb.png', NULL),
(25, 1, 'Rhod Gilbert', 'Rhod', 0, NULL, 0, NULL, 1, 0, '|comedian|', 'Rhod is a comedian who has appeared as a contestant on Taskmaster.', NULL, 'Rhod repeatedly brought in a photo of a scantily-clad and reclined Greg Davies for his prize task submissions.|At the start of most (if not all) of his task attempts, he would close his eyes, rest his head, and meditate for a while, as part of his process for dealing with his ADHD and being able to focus on coming up with a solution.', 'https://www.imdb.com/name/nm2548572/', NULL, NULL, NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/Rhod_Gilbert', NULL, '0025_rhod_gilbert_1.png', '0025_rhod_gilbert_metatag_1.jpg', '0025_rhod_gilbert_pinky_1.png', '0025_rhod_gilbert_search_1.jpg', '0025_rhod_gilbert_thumb_1.png', NULL),
