(157, 1, 'Heino Hansen', 'Heino', 0, NULL, 0, NULL, 1, 0, '|comedian|presenter|actor|screenwriter|', 'Heino is a comedian, presenter and actor who has appeared as a contestant on Stormester.', NULL, 'Heino always either enters the room where the task is introduced with a random item, or else he steals a random item from the location on his way out. He also often looks to the camera and taps his head when he does something he considers to be out-of-the-box thinking.', 'https://www.imdb.com/name/nm3649849/', 'https://www.instagram.com/heinohansendk/', NULL, NULL, NULL, 'https://heinohansen.dk/', 'https://da.wikipedia.org/wiki/Heino_Hansen_(komiker)', 'https://www.youtube.com/user/HeinoHansen/', '0157_heino_hansen.png', '0157_heino_hansen_metatag.jpg', '0157_heino_hansen_pinky.png', '0157_heino_hansen_search.jpg', '0157_heino_hansen_thumb.png', NULL),
