(175, 1, 'Lee Mack', 'Lee', 0, NULL, 0, NULL, 1, 0, '|comedian|presenter|actor|screenwriter|media producer|', 'Lee is a comedian, presenter and actor who has appeared as a contestant on Taskmaster.', 'Lee\'s task outfit was very inconsistent across the show. He changed from trousers to shorts, only sometimes had his jacket and helmet, and his t-shirt changed repeatedly.', NULL, 'https://www.imdb.com/name/nm1056947/', 'https://www.instagram.com/leemackcomedian/', NULL, NULL, NULL, 'http://leemacklive.com/', 'https://en.wikipedia.org/wiki/Lee_Mack', NULL, '0175_lee_mack_1.png', '0175_lee_mack_metatag_1.jpg', '0175_lee_mack_pinky_1.png', '0175_lee_mack_search_1.jpg', '0175_lee_mack_thumb_1.png', NULL),
(176, 1, 'Mike Wozniak', 'Mike', 0, NULL, 1, 1, 1, 0, '|comedian|screenwriter|actor|', 'Mike is a comedian and actor who has appeared as a contestant on Taskmaster, and as the Taskmaster\'s assistant on the spin-off Junior Taskmaster.', 'Mike wore the same outfit for both his pre-filmed tasks and all of his studio appearances.|He repeatedly used the phrases \"Tick-tock, it\'s [insert thing] o\'clock!\" and \"It\'s [insert thing] time!\" during his season.', NULL, 'https://www.imdb.com/name/nm3882814/', NULL, NULL, NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/Mike_Wozniak', NULL, '0176_mike_wozniak_1.png', '0176_mike_wozniak_metatag_1.jpg', '0176_mike_wozniak_pinky_1.png', '0176_mike_wozniak_search_1.jpg', '0176_mike_wozniak_thumb_1.png', NULL),
